WITH UserBadges AS (SELECT U.Id AS UserId, COUNT(B.Id) AS BadgeCount, GROUP_CONCAT(B.Name, ', ') AS BadgeNames FROM Users AS U LEFT JOIN Badges AS B ON U.Id = B.UserId GROUP BY U.Id), RecentPosts AS (SELECT P.Id AS PostId, P.Title, P.CreationDate, P.Score, U.DisplayName AS OwnerDisplayName, ROW_NUMBER() OVER (PARTITION BY U.Id ORDER BY P.CreationDate DESC NULLS FIRST) AS PostRank FROM Posts AS P INNER JOIN Users AS U ON P.OwnerUserId = U.Id WHERE P.CreationDate > CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '30' DAYS), ClosedPosts AS (SELECT PH.PostId, COUNT(*) AS CloseCount, MAX(PH.CreationDate) AS LastClosedDate FROM PostHistory AS PH WHERE PH.PostHistoryTypeId IN (10, 11) GROUP BY PH.PostId) SELECT U.Id AS UserId, U.DisplayName, U.Reputation, U.Location, UB.BadgeCount, UB.BadgeNames, RP.PostId, RP.Title, RP.CreationDate AS PostCreationDate, RP.Score AS PostScore, COALESCE(CP.CloseCount, 0) AS CloseCount, CP.LastClosedDate, ROW_NUMBER() OVER (ORDER BY U.Reputation DESC NULLS FIRST) AS UserRank FROM Users AS U LEFT JOIN UserBadges AS UB ON U.Id = UB.UserId LEFT JOIN RecentPosts AS RP ON U.DisplayName = RP.OwnerDisplayName LEFT JOIN ClosedPosts AS CP ON RP.PostId = CP.PostId WHERE (U.Reputation > 1000 AND CP.CloseCount IS NULL) OR (CP.CloseCount > 1) ORDER BY U.Reputation DESC NULLS FIRST, RP.CreationDate DESC NULLS FIRST LIMIT 50